head.script:
tailwind.config = {
    darkMode: 'class',
    theme: {
        extend: {
            colors: {
                bhajasi: {
                    bg: '#120e0b',
                    panel: '#1b1511',
                    line: '#382a21',
                    gold: '#e7ae63',
                    gold2: '#f4c47d',
                    cream: '#f4eadc',
                    muted: '#ad9d8e'
                }
            },
            fontFamily: {
                sans: ['Noto Sans Devanagari', 'sans-serif']
            }
        }
    }
};

head.b:skin:
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    padding: 0;
    background:
        radial-gradient(
            circle at 50% -10%,
            #2d1d13 0,
            #120e0b 38%,
            #0d0a08 100%
        );
    color: #f4eadc;
    font-family: 'Noto Sans Devanagari', sans-serif;
}

body,
button,
input {
    font-family: 'Noto Sans Devanagari', sans-serif;
}

button {
    -webkit-tap-highlight-color: transparent;
}

::-webkit-scrollbar {
    width: 7px;
}

::-webkit-scrollbar-track {
    background: #120e0b;
}

::-webkit-scrollbar-thumb {
    background: #493526;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #e7ae63;
}

#Blog1,
.blog-posts,
.blog-pager,
.blog-feeds,
.post-outer,
.widget {
    display: none !important;
}

.bhajasi-root {
    min-height: 100vh;
}

.bhajasi-app {
    min-height: 100vh;
    max-width: 760px;
    margin: auto;
    padding-bottom: 74px;
}

.bhajasi-header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(18,14,11,.97);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(231,174,99,.12);
    padding: 10px 17px 9px;
}

.bhajasi-brandline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
}

.bhajasi-brand {
    margin: 0;
    color: #f4c47d;
    font-size: 25px;
    line-height: 1;
    font-weight: 800;
    white-space: nowrap;
}

.bhajasi-tagline {
    color: #ad9d8e;
    font-size: 10px;
    white-space: nowrap;
}

.bhajasi-credit {
    margin-top: 4px;
    color: #89796b;
    font-size: 9px;
}

.bhajasi-progress {
    height: 2px;
    background: #292019;
    margin: 8px -17px -9px;
}

.bhajasi-progress-bar {
    height: 100%;
    width: 0;
    background: #e7ae63;
    transition: width .25s ease;
}

.bhajasi-main {
    padding: 13px 16px 28px;
}

.bhajasi-section {
    margin-bottom: 24px;
}

.bhajasi-section-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 8px 2px 10px;
}

.bhajasi-section-title h2,
.bhajasi-section-title h3 {
    margin: 0;
    color: #fff5e8;
    font-size: 17px;
    line-height: 1.3;
    font-weight: 800;
}

.bhajasi-search {
    margin: 4px 0 19px;
}

.bhajasi-search input {
    width: 100%;
    background: #17110e;
    border: 1px solid #382a21;
    border-radius: 12px;
    padding: 11px 13px;
    color: #f4eadc;
    outline: none;
    font-size: 14px;
}

.bhajasi-search input:focus {
    border-color: #e7ae63;
}

.bhajasi-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 9px;
}

.bhajasi-card {
    width: 100%;
    text-align: left;
    background: linear-gradient(145deg,#211912,#17110e);
    border: 1px solid #382a21;
    border-radius: 15px;
    padding: 14px;
    cursor: pointer;
    color: #f4eadc;
    transition: border-color .2s ease,
                transform .2s ease,
                background .2s ease;
}

.bhajasi-card:hover {
    border-color: #694d34;
    transform: translateY(-1px);
}

.bhajasi-card-title {
    font-size: 15px;
    font-weight: 800;
    line-height: 1.45;
}

.bhajasi-card-sub {
    margin-top: 5px;
    color: #ad9d8e;
    font-size: 10px;
    line-height: 1.55;
}

.bhajasi-saint-card {
    min-height: 72px;
}

.bhajasi-work-card {
    min-height: 76px;
}

.bhajasi-theme-card {
    min-height: 70px;
}

.bhajasi-empty {
    grid-column: 1 / -1;
    border: 1px dashed #382a21;
    border-radius: 14px;
    padding: 18px;
    color: #ad9d8e;
    text-align: center;
    font-size: 13px;
}

.bhajasi-reader-head {
    padding: 1px 1px 14px;
}

.bhajasi-back {
    border: 0;
    background: transparent;
    color: #e7ae63;
    padding: 1px 0 10px;
    cursor: pointer;
    font-size: 12px;
}

.bhajasi-title-row {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 12px;
}

.bhajasi-title {
    margin: 0;
    color: #fff5e8;
    font-size: 25px;
    line-height: 1.3;
    font-weight: 800;
}

.bhajasi-day-label {
    color: #f4c47d;
    font-size: 11px;
    white-space: nowrap;
}

.bhajasi-day-progress {
    margin-bottom: 13px;
}

.bhajasi-day-track {
    display: grid;
    gap: 3px;
    grid-template-columns: repeat(var(--days), 1fr);
}

.bhajasi-day-segment {
    height: 3px;
    border-radius: 8px;
    background: #33271f;
}

.bhajasi-day-segment.done {
    background: #e7ae63;
}

.bhajasi-verse {
    background: linear-gradient(155deg,#211912,#18120f);
    border: 1px solid #33271f;
    border-radius: 16px;
    padding: 16px 14px;
    margin: 9px 0;
}

.bhajasi-verse-text {
    color: #fff1de;
    text-align: center;
    font-size: 18px;
    line-height: 1.75;
    font-weight: 700;
}

.bhajasi-verse-line {
    display: block;
}

.bhajasi-meaning {
    border-top: 1px solid #392c23;
    margin-top: 12px;
    padding-top: 10px;
    text-align: left;
}

.bhajasi-meaning-title {
    color: #f4c47d;
    font-size: 10px;
    font-weight: 800;
    margin-bottom: 4px;
}

.bhajasi-meaning-text {
    margin: 0;
    color: #cdbfb1;
    font-size: 13px;
    line-height: 1.8;
}

.bhajasi-reader-footer {
    display: flex;
    justify-content: space-between;
    margin-top: 11px;
}

.bhajasi-pager {
    width: 38px;
    height: 38px;
    border: 1px solid #382a21;
    background: #1b1511;
    color: #f4c47d;
    border-radius: 11px;
    cursor: pointer;
    font-size: 20px;
}

.bhajasi-pager:disabled {
    opacity: .2;
    cursor: default;
}

.bhajasi-continue-list {
    display: grid;
    gap: 8px;
}

.bhajasi-continue-card {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 14px;
    border: 1px solid #382a21;
    border-radius: 14px;
    background: linear-gradient(145deg,#211912,#17110e);
    color: #f4eadc;
    cursor: pointer;
    text-align: left;
}

.bhajasi-continue-main {
    min-width: 0;
}

.bhajasi-continue-saint {
    color: #f4c47d;
    font-size: 10px;
    font-weight: 700;
}

.bhajasi-continue-work {
    color: #fff5e8;
    font-size: 14px;
    font-weight: 800;
}

.bhajasi-continue-day {
    color: #ad9d8e;
    font-size: 10px;
    white-space: nowrap;
}

.bhajasi-bottom {
    position: fixed;
    z-index: 60;
    left: 50%;
    bottom: 0;
    transform: translateX(-50%);
    width: min(760px,100%);
    padding: 7px 14px calc(7px + env(safe-area-inset-bottom));
    background: rgba(18,14,11,.98);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-top: 1px solid rgba(231,174,99,.13);
    display: flex;
    justify-content: space-around;
}

.bhajasi-bottom button {
    border: 0;
    background: transparent;
    color: #9e9186;
    font-size: 10px;
    cursor: pointer;
}

.bhajasi-bottom button.active {
    color: #f4c47d;
}

.bhajasi-bottom-icon {
    display: block;
    font-size: 16px;
    margin-bottom: 1px;
}

.bhajasi-hidden {
    display: none !important;
}

@media (min-width: 600px) {

    .bhajasi-main {
        padding: 16px 25px 30px;
    }

    .bhajasi-grid {
        grid-template-columns: repeat(3, 1fr);
    }

    .bhajasi-verse {
        padding: 18px 20px;
    }

    .bhajasi-verse-text {
        font-size: 20px;
    }
}

@media (max-width: 520px) {

    .bhajasi-brandline {
        gap: 8px;
    }

    .bhajasi-brand {
        font-size: 23px;
    }

    .bhajasi-tagline {
        font-size: 8px;
    }
}

body.script:
//

const DATA_BASE =
    'https://raw.githubusercontent.com/project-bharat/bhajasi/main/data/saints/';

const PROGRESS_KEY =
    'bhajasi_reading_progress_v1';

const {
    useState,
    useEffect,
    useMemo,
    useRef
} = React;


/* -------------------------------------------------------
   HELPERS
------------------------------------------------------- */

function readProgress() {
    try {
        return JSON.parse(
            localStorage.getItem(PROGRESS_KEY) || '{}'
        );
    } catch {
        return {};
    }
}

function writeProgress(key, value) {
    const old = readProgress();

    old[key] = {
        ...(old[key] || {}),
        ...value
    };

    localStorage.setItem(
        PROGRESS_KEY,
        JSON.stringify(old)
    );
}

function makeWorkKey(saint, work) {
    return saint.id + '::' + work.title;
}

function splitPoem(text) {

    if (!text) return [];

    return String(text)
        .split(/(?<=।|॥|\.)(?:\s+|$)/u)
        .map(x => x.trim())
        .filter(Boolean);
}

function allWorks(saints) {

    return saints.flatMap(saint =>
        saint.works.map((work, index) => ({
            saint,
            work,
            index
        }))
    );
}


/* -------------------------------------------------------
   APP
------------------------------------------------------- */

function App() {

    const [saints, setSaints] = useState([]);

    const [view, setView] = useState('home');

    const [selectedSaint, setSelectedSaint] =
        useState(null);

    const [selectedWork, setSelectedWork] =
        useState(null);

    const [day, setDay] = useState(1);

    const [search, setSearch] =
        useState('');

    const [theme, setTheme] =
        useState(null);

    const [loading, setLoading] =
        useState(true);

    const touchStart = useRef(null);


    /* ---------------------------------------------------
       LOAD SANT DATA
    --------------------------------------------------- */

    useEffect(() => {

        async function loadData() {

            try {

                const indexResponse =
                    await fetch(DATA_BASE + 'index.json');

                const files =
                    await indexResponse.json();

                const loaded =
                    await Promise.all(
                        files.map(async file => {

                            const response =
                                await fetch(
                                    DATA_BASE + file
                                );

                            return response.json();
                        })
                    );

                setSaints(loaded);

            } catch (error) {

                console.error(
                    'Bhajasi data loading error:',
                    error
                );

            } finally {

                setLoading(false);
            }
        }

        loadData();

    }, []);


    /* ---------------------------------------------------
       PROGRESS
    --------------------------------------------------- */

    const progress =
        readProgress();


    function openSaint(saint) {

        setSelectedSaint(saint);
        setSelectedWork(null);
        setView('works');

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function openWork(saint, work, initialDay = 1) {

        setSelectedSaint(saint);
        setSelectedWork(work);

        const maxDay =
            Math.max(
                1,
                Number(work.days || 1)
            );

        const safeDay =
            Math.min(
                Math.max(1, initialDay),
                maxDay
            );

        setDay(safeDay);
        setView('reader');

        writeProgress(
            makeWorkKey(saint, work),
            {
                day: safeDay
            }
        );

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function goHome() {

        setView('home');
        setSelectedSaint(null);
        setSelectedWork(null);
        setTheme(null);

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function goSaints() {

        setView('saints');

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function goToday() {

        setView('today');

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function nextDay() {

        if (!selectedWork) return;

        const total =
            Number(selectedWork.days || 1);

        if (day >= total) return;

        const next =
            day + 1;

        setDay(next);

        writeProgress(
            makeWorkKey(
                selectedSaint,
                selectedWork
            ),
            {
                day: next
            }
        );

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    function previousDay() {

        if (day <= 1) return;

        const previous =
            day - 1;

        setDay(previous);

        writeProgress(
            makeWorkKey(
                selectedSaint,
                selectedWork
            ),
            {
                day: previous
            }
        );

        window.scrollTo({
            top: 0,
            behavior: 'smooth'
        });
    }


    /* ---------------------------------------------------
       SWIPE
    --------------------------------------------------- */

    function onTouchStart(event) {

        if (view !== 'reader') return;

        touchStart.current =
            event.changedTouches[0].clientX;
    }


    function onTouchEnd(event) {

        if (
            view !== 'reader' ||
            touchStart.current === null
        ) return;

        const end =
            event.changedTouches[0].clientX;

        const distance =
            end - touchStart.current;

        if (Math.abs(distance) < 55) return;

        if (distance < 0) {

            nextDay();

        } else {

            previousDay();
        }

        touchStart.current = null;
    }


    /* ---------------------------------------------------
       SEARCH
    --------------------------------------------------- */

    const filteredSaints =
        useMemo(() => {

            const q =
                search.trim().toLowerCase();

            if (!q) return saints;

            return saints.filter(saint => {

                const content =
                    [
                        saint.name,
                        saint.search,
                        ...(saint.works || [])
                            .map(w => w.title)
                    ]
                    .join(' ')
                    .toLowerCase();

                return content.includes(q);
            });

        }, [saints, search]);


    /* ---------------------------------------------------
       THEMES
    --------------------------------------------------- */

    const themes = [

        {
            title: 'नामस्मरण',
            keys: ['नाम', 'हरि', 'हरी', 'राम', 'कृष्ण', 'हरिपाठ']
        },

        {
            title: 'भक्ती',
            keys: ['भक्ति', 'भक्त', 'देव', 'दैवत']
        },

        {
            title: 'ज्ञान',
            keys: ['ज्ञान', 'विवेक', 'आत्म', 'तत्त्व']
        },

        {
            title: 'समता',
            keys: ['समता', 'सर्व', 'एकत्व']
        },

        {
            title: 'सेवा',
            keys: ['सेवा', 'दया', 'करुणा', 'परोपकार']
        },

        {
            title: 'वैराग्य',
            keys: ['वैराग्य', 'मोह', 'प्रपंच']
        },

        {
            title: 'सदाचार',
            keys: ['सत्य', 'नीती', 'धर्म', 'आचार']
        },

        {
            title: 'मनःशांती',
            keys: ['शांत', 'शांती', 'मन', 'स्थिर']
        }

    ];


    /* ---------------------------------------------------
       CONTINUE / TODAY
    --------------------------------------------------- */

    const continueItems = [];

    saints.forEach(saint => {

        (saint.works || []).forEach(work => {

            const key =
                makeWorkKey(saint, work);

            const saved =
                progress[key];

            if (saved) {

                continueItems.push({
                    saint,
                    work,
                    day: Number(saved.day || 1)
                });
            }

        });

    });


    /* ---------------------------------------------------
       READER ENTRIES
    --------------------------------------------------- */

    let currentEntries = [];

    if (selectedWork) {

        currentEntries =
            (selectedWork.entries || [])
                .filter(
                    entry =>
                        Number(entry.day) === Number(day)
                );
    }


    /* ---------------------------------------------------
       PROGRESS BAR
    --------------------------------------------------- */

    const totalDays =
        selectedWork
            ? Number(selectedWork.days || 1)
            : 1;

    const progressPercent =
        selectedWork
            ? ((day - 1) / Math.max(1, totalDays - 1)) * 100
            : 0;


    /* ---------------------------------------------------
       RENDER
    --------------------------------------------------- */

    if (loading) {

        return (

            <div className='bhajasi-root'>
                <div className='bhajasi-app'>

                    <header className='bhajasi-header'>

                        <div className='bhajasi-brandline'>

                            <h1 className='bhajasi-brand'>
                                भजासी
                            </h1>

                            <span className='bhajasi-tagline'>
                                संतवाणी • अभंग • हरिनाम • चिंतन
                            </span>

                        </div>

                        <div className='bhajasi-credit'>
                            संकलन: भरत रास्वे
                        </div>

                    </header>

                    <main className='bhajasi-main'>

                        <div className='bhajasi-empty'>
                            साहित्य लोड होत आहे…
                        </div>

                    </main>

                </div>
            </div>

        );
    }


    return (

        <div
            className='bhajasi-root'
            onTouchStart={onTouchStart}
            onTouchEnd={onTouchEnd}
        >

            <div className='bhajasi-app'>


                {/* HEADER */}

                <header className='bhajasi-header'>

                    <div className='bhajasi-brandline'>

                        <h1 className='bhajasi-brand'>
                            भजासी
                        </h1>

                        <span className='bhajasi-tagline'>
                            संतवाणी • अभंग • हरिनाम • चिंतन
                        </span>

                    </div>

                    <div className='bhajasi-credit'>
                        संकलन: भरत रास्वे
                    </div>

                    <div className='bhajasi-progress'>

                        <div
                            className='bhajasi-progress-bar'
                            style={{
                                width:
                                    view === 'reader'
                                        ? `${progressPercent}%`
                                        : '0%'
                            }}
                        />

                    </div>

                </header>


                <main className='bhajasi-main'>


                    {/* HOME */}

                    {view === 'home' && (

                        <>

                            <div className='bhajasi-search'>

                                <input
                                    value={search}
                                    onChange={
                                        e =>
                                            setSearch(
                                                e.target.value
                                            )
                                    }
                                    placeholder='संत किंवा साहित्य शोधा…'
                                    autoComplete='off'
                                />

                            </div>


                            <section className='bhajasi-section'>

                                <div className='bhajasi-section-title'>

                                    <h2>
                                        संतांनुसार
                                    </h2>

                                </div>

                                <div className='bhajasi-grid'>

                                    {filteredSaints.map(saint => (

                                        <button
                                            key={saint.id}
                                            className='bhajasi-card bhajasi-saint-card'
                                            onClick={() =>
                                                openSaint(saint)
                                            }
                                        >

                                            <div className='bhajasi-card-title'>
                                                {saint.name}
                                            </div>

                                            <div className='bhajasi-card-sub'>
                                                {(saint.works || [])
                                                    .map(w => w.title)
                                                    .join(' • ')}
                                            </div>

                                        </button>

                                    ))}

                                </div>

                            </section>


                            <section className='bhajasi-section'>

                                <div className='bhajasi-section-title'>

                                    <h2>
                                        ग्रंथांनुसार
                                    </h2>

                                </div>

                                <div className='bhajasi-grid'>

                                    {allWorks(filteredSaints)
                                        .map(item => (

                                            <button
                                                key={
                                                    item.saint.id +
                                                    item.work.title
                                                }
                                                className='bhajasi-card bhajasi-work-card'
                                                onClick={() =>
                                                    openWork(
                                                        item.saint,
                                                        item.work
                                                    )
                                                }
                                            >

                                                <div className='bhajasi-card-title'>
                                                    {item.work.title}
                                                </div>

                                                <div className='bhajasi-card-sub'>
                                                    {item.saint.name}
                                                </div>

                                            </button>

                                        ))}

                                </div>

                            </section>


                            <section className='bhajasi-section'>

                                <div className='bhajasi-section-title'>

                                    <h2>
                                        शिकवणीनुसार
                                    </h2>

                                </div>

                                <div className='bhajasi-grid'>

                                    {themes.map((item, index) => (

                                        <button
                                            key={index}
                                            className='bhajasi-card bhajasi-theme-card'
                                            onClick={() => {

                                                setTheme(item);
                                                setView('theme');

                                            }}
                                        >

                                            <div className='bhajasi-card-title'>
                                                {item.title}
                                            </div>

                                            <div className='bhajasi-card-sub'>
                                                संबंधित संतवाणी
                                            </div>

                                        </button>

                                    ))}

                                </div>

                            </section>

                        </>

                    )}


                    {/* TODAY */}

                    {view === 'today' && (

                        <section className='bhajasi-section'>

                            <div className='bhajasi-section-title'>

                                <h2>
                                    आजचे
                                </h2>

                            </div>

                            {continueItems.length === 0 ? (

                                <div className='bhajasi-empty'>

                                    अजून कोणतेही साहित्य सुरू केलेले नाही.

                                </div>

                            ) : (

                                <div className='bhajasi-continue-list'>

                                    {continueItems.map(item => (

                                        <button
                                            key={
                                                makeWorkKey(
                                                    item.saint,
                                                    item.work
                                                )
                                            }
                                            className='bhajasi-continue-card'
                                            onClick={() =>
                                                openWork(
                                                    item.saint,
                                                    item.work,
                                                    item.day
                                                )
                                            }
                                        >

                                            <div className='bhajasi-continue-main'>

                                                <div className='bhajasi-continue-saint'>
                                                    {item.saint.name}
                                                </div>

                                                <div className='bhajasi-continue-work'>
                                                    {item.work.title}
                                                </div>

                                            </div>

                                            <div className='bhajasi-continue-day'>
                                                दिवस {item.day}
                                            </div>

                                        </button>

                                    ))}

                                </div>

                            )}

                        </section>

                    )}


                    {/* SAINT DIRECTORY */}

                    {view === 'saints' && (

                        <section className='bhajasi-section'>

                            <div className='bhajasi-section-title'>

                                <h2>
                                    संत
                                </h2>

                            </div>

                            <div className='bhajasi-grid'>

                                {saints.map(saint => (

                                    <button
                                        key={saint.id}
                                        className='bhajasi-card bhajasi-saint-card'
                                        onClick={() =>
                                            openSaint(saint)
                                        }
                                    >

                                        <div className='bhajasi-card-title'>
                                            {saint.name}
                                        </div>

                                        <div className='bhajasi-card-sub'>
                                            {(saint.works || [])
                                                .map(w => w.title)
                                                .join(' • ')}
                                        </div>

                                    </button>

                                ))}

                            </div>

                        </section>

                    )}


                    {/* WORK LIST */}

                    {view === 'works' && selectedSaint && (

                        <section>

                            <div className='bhajasi-reader-head'>

                                <button
                                    className='bhajasi-back'
                                    onClick={goSaints}
                                >
                                    ← संतांकडे परत
                                </button>

                                <div className='bhajasi-title-row'>

                                    <h2 className='bhajasi-title'>
                                        {selectedSaint.name}
                                    </h2>

                                </div>

                            </div>


                            <div className='bhajasi-grid'>

                                {(selectedSaint.works || [])
                                    .map((work, index) => (

                                        <button
                                            key={index}
                                            className='bhajasi-card bhajasi-work-card'
                                            onClick={() =>
                                                openWork(
                                                    selectedSaint,
                                                    work
                                                )
                                            }
                                        >

                                            <div className='bhajasi-card-title'>
                                                {work.title}
                                            </div>

                                            <div className='bhajasi-card-sub'>
                                                दिवस {work.days || 1}
                                            </div>

                                        </button>

                                    ))}

                            </div>

                        </section>

                    )}


                    {/* READER */}

                    {view === 'reader' &&
                        selectedSaint &&
                        selectedWork && (

                        <section>

                            <div className='bhajasi-reader-head'>

                                <button
                                    className='bhajasi-back'
                                    onClick={() =>
                                        openSaint(
                                            selectedSaint
                                        )
                                    }
                                >
                                    ← साहित्याकडे परत
                                </button>


                                <div className='bhajasi-day-progress'>

                                    <div
                                        className='bhajasi-day-track'
                                        style={{
                                            '--days':
                                                totalDays
                                        }}
                                    >

                                        {Array
                                            .from({
                                                length:
                                                    totalDays
                                            })
                                            .map(
                                                (_, index) => (

                                                    <span
                                                        key={index}
                                                        className={
                                                            'bhajasi-day-segment ' +
                                                            (
                                                                index + 1 <= day
                                                                    ? 'done'
                                                                    : ''
                                                            )
                                                        }
                                                    />

                                                )
                                            )}

                                    </div>

                                </div>


                                <div className='bhajasi-title-row'>

                                    <h2 className='bhajasi-title'>
                                        {selectedWork.title}
                                    </h2>

                                    <span className='bhajasi-day-label'>
                                        दिवस {day}
                                    </span>

                                </div>

                            </div>


                            {currentEntries.length === 0 ? (

                                <div className='bhajasi-empty'>

                                    या दिवसासाठी साहित्य उपलब्ध नाही.

                                </div>

                            ) : (

                                currentEntries.map(
                                    (entry, index) => (

                                        <article
                                            key={index}
                                            className='bhajasi-verse'
                                        >

                                            <div className='bhajasi-verse-text'>

                                                {splitPoem(
                                                    entry.text
                                                ).map(
                                                    (line, lineIndex) => (

                                                        <span
                                                            key={lineIndex}
                                                            className='bhajasi-verse-line'
                                                        >
                                                            {line}
                                                        </span>

                                                    )
                                                )}

                                            </div>


                                            {entry.meaning && (

                                                <div className='bhajasi-meaning'>

                                                    <div className='bhajasi-meaning-title'>
                                                        अर्थ
                                                    </div>

                                                    <p className='bhajasi-meaning-text'>
                                                        {entry.meaning}
                                                    </p>

                                                </div>

                                            )}

                                        </article>

                                    )
                                )

                            )}


                            <div className='bhajasi-reader-footer'>

                                <button
                                    className='bhajasi-pager'
                                    onClick={previousDay}
                                    disabled={day <= 1}
                                    aria-label='मागील दिवस'
                                >
                                    ←
                                </button>


                                <button
                                    className='bhajasi-pager'
                                    onClick={nextDay}
                                    disabled={
                                        day >= totalDays
                                    }
                                    aria-label='पुढील दिवस'
                                >
                                    →
                                </button>

                            </div>

                        </section>

                    )}


                    {/* THEME */}

                    {view === 'theme' && theme && (

                        <section>

                            <div className='bhajasi-reader-head'>

                                <button
                                    className='bhajasi-back'
                                    onClick={goHome}
                                >
                                    ← मुख्य
                                </button>

                                <div className='bhajasi-title-row'>

                                    <h2 className='bhajasi-title'>
                                        {theme.title}
                                    </h2>

                                </div>

                            </div>


                            <div className='bhajasi-grid'>

                                {allWorks(saints)
                                    .filter(item => {

                                        const source =
                                            JSON.stringify(
                                                item.work
                                            ).toLowerCase();

                                        return theme.keys.some(
                                            key =>
                                                source.includes(
                                                    key.toLowerCase()
                                                )
                                        );

                                    })
                                    .map(item => (

                                        <button
                                            key={
                                                item.saint.id +
                                                item.work.title
                                            }
                                            className='bhajasi-card'
                                            onClick={() =>
                                                openWork(
                                                    item.saint,
                                                    item.work
                                                )
                                            }
                                        >

                                            <div className='bhajasi-card-title'>
                                                {item.work.title}
                                            </div>

                                            <div className='bhajasi-card-sub'>
                                                {item.saint.name}
                                            </div>

                                        </button>

                                    ))}

                            </div>

                        </section>

                    )}

                </main>


                {/* BOTTOM NAVIGATION */}

                <nav className='bhajasi-bottom'>

                    <button
                        className={
                            view === 'home'
                                ? 'active'
                                : ''
                        }
                        onClick={goHome}
                    >

                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-house'></i>
                        </span>

                        मुख्य

                    </button>


                    <button
                        className={
                            view === 'saints' ||
                            view === 'works'
                                ? 'active'
                                : ''
                        }
                        onClick={goSaints}
                    >

                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-hands-praying'></i>
                        </span>

                        संत

                    </button>


                    <button
                        className={
                            view === 'today'
                                ? 'active'
                                : ''
                        }
                        onClick={goToday}
                    >

                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-book-open'></i>
                        </span>

                        आजचे

                    </button>

                </nav>

            </div>

        </div>

    );

}


const root =
    ReactDOM.createRoot(
        document.getElementById(
            'bhajasi-root'
        )
    );

root.render(
    <App />
);

